headers.header:
name: Trusted CI selection
on:
  workflow_call:
    outputs:
      docs_only:
        value: ${{ jobs.select.outputs.docs_only }}
      core:
        value: ${{ jobs.select.outputs.core }}
      integration:
        value: ${{ jobs.select.outputs.integration }}
      source:
        value: ${{ jobs.select.outputs.source }}
      daemon:
        value: ${{ jobs.select.outputs.daemon }}
      desktop:
        value: ${{ jobs.select.outputs.desktop }}
      image:
        value: ${{ jobs.select.outputs.image }}
      analytics:
        value: ${{ jobs.select.outputs.analytics }}
      db:
        value: ${{ jobs.select.outputs.db }}
      units:
        value: ${{ jobs.select.outputs.units }}
      db_suites:
        value: ${{ jobs.select.outputs.db_suites }}
      db_matrix:
        value: ${{ jobs.select.outputs.db_matrix }}
permissions:
  contents: read
